// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target) public {
        vm.assume(amount > 0);
        vm.assume(target != address(c));
        Reverter reverter = new Reverter();
        address reverterAddr = address(reverter);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        bool ok;
        vm.prank(c.owner());
        try c.sendMoney(reverterAddr, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        bool ruleHolds = (ok == false) && (address(c).balance == balanceBefore);
        assertTrue(ruleHolds);
    }
}

contract Reverter {
    fallback() external payable {
        revert("Reverter: no ETH accepted");
    }
}
